async function main({ RawVideoOutput, RawImageOutput }) {
var mediaId = null
var mediaType = null
var mediaUri = null
var adbCmd = null
var mediaFormat = null

var videoRows = RawVideoOutput.split('Row:')
var i = 0
while (i < videoRows.length) {
    if (videoRows[i].indexOf('bucket_display_name=Download') !== -1) {
        var matchId = videoRows[i].match(/_id=(\d+)/)
        var matchMime = videoRows[i].match(/mime_type=([^\s,]+)/)
        if (matchId && matchMime) {
            mediaId = matchId[1]
            mediaType = matchMime[1]
            mediaUri = 'content://media/external/video/media/' + mediaId
        }
    }
    i++
}

if (!mediaId) {
    var imageRows = RawImageOutput.split('Row:')
    var j = 0
    while (j < imageRows.length) {
        if (imageRows[j].indexOf('bucket_display_name=Download') !== -1) {
            var matchId2 = imageRows[j].match(/_id=(\d+)/)
            var matchMime2 = imageRows[j].match(/mime_type=([^\s,]+)/)
            if (matchId2 && matchMime2) {
                mediaId = matchId2[1]
                mediaType = matchMime2[1]
                mediaUri = 'content://media/external/images/media/' + mediaId
            }
        }
        j++
    }
}

if (mediaType && mediaType.indexOf('video') !== -1) {
    mediaFormat = 'VIDEO'
    adbCmd = 'am start -n com.instagram.android/com.instagram.mainactivity.InstagramMainActivity ; sleep 4 ; am start -a com.instagram.share.ADD_TO_STORY -n com.instagram.android/com.instagram.share.handleractivity.StoryShareHandlerActivity --eu android.intent.extra.STREAM ' + mediaUri + ' -t video/mp4 --grant-read-uri-permission'
} else {
    mediaFormat = 'IMAGE'
    adbCmd = 'am start -n com.instagram.android/com.instagram.mainactivity.InstagramMainActivity ; sleep 4 ; am start -a com.instagram.share.ADD_TO_STORY -n com.instagram.android/com.instagram.share.handleractivity.StoryShareHandlerActivity --eu android.intent.extra.STREAM ' + mediaUri + ' -t ' + mediaType + ' --grant-read-uri-permission'
}

return { AdbCmd: adbCmd, MediaFormat: mediaFormat }
}

async function main({ WmSize }) {
  var m = String(WmSize).match(/(\d+)x(\d+)/)
  var w = m ? parseInt(m[1]) : 1080
  var h = m ? parseInt(m[2]) : 1920
  var sx = Math.floor(w/2), sy = Math.floor(h*0.47)
  var tx = Math.floor(w*0.72), ty = Math.floor(h*0.80)
  return { DragCmd: 'input draganddrop ' + sx + ' ' + sy + ' ' + tx + ' ' + ty + ' 1500' }
}
